//! The built-in function registry: Spark's built-in names (ASCII
//! case-insensitive, each alias its own entry) bound to their analysis
//! signature and their execution.
//!
//! Each [`FunctionDef`] carries what the analyzer and the optimizer need:
//! the kind, the arity, the implicit casts and result type, whether it is
//! deterministic, and the first Spark release line that has it. The last
//! three come from Spark's own catalog ([`SparkFunction`], generated by
//! running each supported release), so they are not restated here.
//!
//! A name Spark has and Krishiv does not implement is
//! [`Lookup::KnownUnsupported`] in profiles that have it, and
//! [`Lookup::NotFound`] in older ones (as for an unknown name).

mod catalog;
mod conditional;
mod defs;
mod hashing;
mod math;

use std::collections::HashMap;
use std::fmt;
use std::sync::{Arc, LazyLock};

pub use catalog::SparkFunction;
pub use defs::legacy_day_count;

use crate::signature::{Arity, FunctionKind, Inputs, ResultType, SparkProfile};

/// How a function is executed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Execution {
    /// By [`crate::scalar::bind_scalar`] under the function's name.
    Scalar,
    /// By this aggregate of the executor.
    Aggregate(Aggregate),
    /// By the expression evaluator itself, like the canonical operators:
    /// the conditionals, which evaluate their arguments lazily
    /// (`krishiv_kernels::conditional`).
    Evaluator,
}

/// The aggregates the executor implements.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Aggregate {
    /// `count`.
    Count,
    /// `sum`.
    Sum,
    /// `avg` / `mean`.
    Avg,
    /// `min`.
    Min,
    /// `max`.
    Max,
    /// `first` / `first_value`; `ignoreNulls` is the second argument.
    First,
    /// `last` / `last_value`; `ignoreNulls` is the second argument.
    Last,
}

/// A built-in function.
#[non_exhaustive]
pub struct FunctionDef {
    /// The name (lower case), as Spark lists it; an alias is its own entry.
    pub name: &'static str,
    /// A handle for this process (the definition's position); never part
    /// of a plan key.
    pub id: u32,
    /// Scalar, aggregate, ...
    pub kind: FunctionKind,
    /// Whether Spark analyzes a call as deterministic.
    pub deterministic: bool,
    /// The oldest release line that has it.
    pub since: SparkProfile,
    /// The argument counts it takes.
    pub arity: Arity,
    /// How its arguments are implicitly cast.
    pub inputs: Inputs,
    /// Its result type for the (cast) argument types.
    pub result: ResultType,
    /// How it runs.
    pub execution: Execution,
}

impl fmt::Debug for FunctionDef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("FunctionDef")
            .field("name", &self.name)
            .field("id", &self.id)
            .field("kind", &self.kind)
            .field("deterministic", &self.deterministic)
            .field("since", &self.since)
            .field("arity", &self.arity)
            .field("inputs", &self.inputs)
            .field("execution", &self.execution)
            .finish_non_exhaustive()
    }
}

/// A registry lookup.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub enum Lookup<'a> {
    /// Found.
    Found(&'a FunctionDef),
    /// Spark has it in this profile but Krishiv does not implement it.
    KnownUnsupported,
    /// Spark does not have it in this profile.
    NotFound,
}

/// The built-in functions.
#[derive(Debug)]
pub struct Registry {
    defs: HashMap<&'static str, FunctionDef>,
    spark: HashMap<&'static str, SparkFunction>,
    /// Definitions without a catalog row (a registry bug; the tests check
    /// there are none). They are not registered.
    unlisted: Vec<&'static str>,
}

/// The process-wide registry.
static BUILTINS: LazyLock<Registry> = LazyLock::new(Registry::build);

/// The built-in function registry.
#[must_use]
pub fn builtins() -> &'static Registry {
    &BUILTINS
}

impl Registry {
    fn build() -> Self {
        let (rows, _) = catalog::load();
        let spark: HashMap<&'static str, SparkFunction> =
            rows.into_iter().map(|r| (r.name, r)).collect();
        let mut defs = HashMap::new();
        let mut unlisted = Vec::new();
        for (id, spec) in (0_u32..).zip(defs::specs()) {
            let Some(row) = spark.get(spec.name) else {
                unlisted.push(spec.name);
                continue;
            };
            defs.insert(
                spec.name,
                FunctionDef {
                    name: spec.name,
                    id,
                    kind: spec.kind,
                    // A function Spark rejects in every probe is taken as
                    // nondeterministic: the optimizer then never moves it.
                    deterministic: row.deterministic.unwrap_or(false),
                    since: row.since,
                    arity: row.arity.clone(),
                    inputs: spec.inputs,
                    result: Arc::new(spec.result),
                    execution: spec.execution,
                },
            );
        }
        Self {
            defs,
            spark,
            unlisted,
        }
    }

    /// The function `name` (ASCII case-insensitive) in `profile`.
    #[must_use]
    pub fn lookup(&self, name: &str, profile: SparkProfile) -> Lookup<'_> {
        let lower = name.to_ascii_lowercase();
        if let Some(def) = self.defs.get(lower.as_str()) {
            return if profile >= def.since {
                Lookup::Found(def)
            } else {
                Lookup::NotFound
            };
        }
        match self.spark.get(lower.as_str()) {
            Some(s) if profile >= s.since => Lookup::KnownUnsupported,
            _ => Lookup::NotFound,
        }
    }

    /// Every implemented function, sorted by name.
    #[must_use]
    pub fn functions(&self) -> Vec<&FunctionDef> {
        let mut out: Vec<&FunctionDef> = self.defs.values().collect();
        out.sort_unstable_by_key(|d| d.name);
        out
    }

    /// Spark's catalog entry for `name` (lower case).
    #[must_use]
    pub fn spark_function(&self, name: &str) -> Option<&SparkFunction> {
        self.spark.get(name)
    }

    /// The number of names in Spark's catalog (all release lines).
    #[must_use]
    pub fn spark_function_count(&self) -> usize {
        self.spark.len()
    }

    /// Definitions whose name Spark's catalog does not have; they are not
    /// registered (empty unless a definition is misnamed).
    #[must_use]
    pub fn unlisted(&self) -> &[&'static str] {
        &self.unlisted
    }

    /// Changes whenever a lookup could answer differently; the built-ins
    /// are fixed per build.
    #[must_use]
    pub const fn version(&self) -> u64 {
        0
    }
}

